const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const os = require('node:os');
const fg = require('./out');
const root = fs.mkdtempSync(path.join(os.tmpdir(), 'f31-check-'));
try {
  fs.mkdirSync(path.join(root, 'blocked', 'deep'), { recursive: true });
  fs.mkdirSync(path.join(root, 'keep'), { recursive: true });
  fs.writeFileSync(path.join(root, 'blocked', 'deep', 'secret.txt'), 'x');
  fs.writeFileSync(path.join(root, 'keep', 'a.txt'), 'x');
  fs.writeFileSync(path.join(root, 'root.txt'), 'x');
  const sentinel = new Error('identity');
  assert.throws(() => fg.sync('**/*', { cwd: root, filter: () => { throw sentinel; } }), error => error === sentinel);
  const seen = [];
  const values = fg.sync('**/*', { cwd: root, filter: entry => { seen.push(entry); return entry.path !== 'blocked'; }, fs: { readdirSync: (...args) => fs.readdirSync(...args) } });
  assert.deepEqual(values.sort(), ['keep/a.txt', 'root.txt']);
  assert.ok(seen.some(entry => entry.path === 'blocked' && entry.dirent));
  console.log(JSON.stringify({ callbackErrorIdentity: true, values, seen: seen.map(entry => entry.path).sort() }));
} finally { fs.rmSync(root, { recursive: true, force: true }); }
NODE

